-- PT122-S4-Q9. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT122-S4-Q9$batch09$ AND q.stimulus=$batch09$Executive: In order to add to our profits, I was planning to promote and distribute herbal tinctures. However, some members of my advisory staff questioned the medical efficacy of such products. So I have consulted a variety of reliable medical publications, and these likewise claim that herbal tinctures are ineffective. Therefore, I must conclude that marketing such products would not produce the result I intended.$batch09$ AND q.prompt=$batch09$The executive's reasoning most closely conforms to which one of the following generalizations?$batch09$ AND q.correct_choice=$batch09$E$batch09$) THEN RAISE EXCEPTION 'Question changed: PT122-S4-Q9'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT122-S4-Q9$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S4-Q9'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT122-S4-Q9$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Marketing herbal tinctures wouldn't produce the result the executive wanted, which is more profit.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Advisers questioned whether the tinctures work, and a variety of reliable medical publications say they're ineffective.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The evidence ends at "reliable sources say these products don't work." The conclusion is about profit. So the principle has to connect reliable authorities calling a product ineffective to the product not being profitable.$batch09$), (3, $batch09$Goal$batch09$, $batch09$If reliable authorities declare a product ineffective, promoting it won't be profitable.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT122-S4-Q9$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The executive never asks what makes a publication reliable. The publications are already called reliable.$batch09$), ($batch09$B$batch09$, $batch09$This is the trap, picked by 5%. It takes us from reliable sources to "the tinctures are ineffective." But the executive concludes something about profit, and B says nothing about profit. B also needs a majority of reliable sources, and the executive only consulted "a variety."$batch09$), ($batch09$C$batch09$, $batch09$This says consulting publications isn't a reliable basis for predicting profit. That's exactly what the executive did, so C undermines the reasoning.$batch09$), ($batch09$D$batch09$, $batch09$This is about adverse effects. The publications say the tinctures don't work, not that they cause harm.$batch09$), ($batch09$E$batch09$, $batch09$The trigger is a number of reliable authorities calling the products ineffective, which is the executive's evidence. The outcome is that promoting them won't be profitable, which is the conclusion. E is the whole argument as a rule.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT122-S4-Q9$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
